import { test } from 'node:test'
import { posix } from 'node:path'

import { Vfs, buildVfsBundle, loadNodeModules } from '../stasis/src/vfs-bundle.js'

// @exodus/stasis/vfs-bundle with yarn 1, over a project held in a Vfs, which @preventive/deptree reads
// the yarn.lock, the package.json of the root and of every workspace, and the .yarnrc and .npmrc
// from. Every lockfile here locks no registry package, so nothing is fetched.

const project = (files) => {
  const vfs = new Vfs()
  for (const [rel, text] of Object.entries(files)) {
    vfs.mkdir(posix.dirname(`/${rel}`), { recursive: true })
    vfs.writeFile(`/${rel}`, typeof text === 'string' ? text : `${JSON.stringify(text)}\n`)
  }
  return vfs
}

const load = (options) => loadNodeModules({ packageManager: 'yarn1', ...options })

const LOCKFILE = '# THIS IS AN AUTOGENERATED FILE. DO NOT EDIT THIS FILE DIRECTLY.\n# yarn lockfile v1\n\n\n'

test('yarn1: lays out, into a Vfs of its own, the yarn.lock of cwd or the nearest parent, as the yarn packageManager pins, yarn 1.22.22 without one', async (t) => {
  const files = { 'package.json': { name: 'p', version: '1.0.0' }, 'yarn.lock': LOCKFILE, 'src/deep/a.js': '' }
  const vfs = project(files)
  const tree = await load({ vfs, cwd: '/src/deep' })
  t.assert.equal(tree.root, '/')
  t.assert.equal(tree.packageManager, 'yarn1')
  t.assert.equal(tree.packageManagerVersion, '1.22.22')
  t.assert.deepEqual([...tree.projects], ['.'])
  t.assert.deepEqual(tree.vfs.readdir('/'), ['node_modules'])
  t.assert.equal(vfs.isDirectory('/node_modules'), false, 'the project\'s Vfs is only read')
  t.assert.equal(tree.host.stat('/src/deep/a.js').isFile(), true)

  files['package.json'] = { name: 'p', version: '1.0.0', packageManager: 'yarn@1.22.19' }
  t.assert.equal((await load({ vfs: project(files) })).packageManagerVersion, '1.22.19')
  t.assert.equal((await load({ vfs: project(files), packageManagerVersion: '1.22.19' })).packageManagerVersion, '1.22.19')
  await t.assert.rejects(load({ vfs: project(files), packageManagerVersion: '1.22.22' }), /packageManager: the project is installed by yarn 1\.22\.19, which corepack runs, not 1\.22\.22/u)
  files['package.json'] = { name: 'p', version: '1.0.0', packageManager: 'yarn@4.5.0' }
  await t.assert.rejects(load({ vfs: project(files) }), /host\.yarn: yarn "4\.5\.0" is not supported: only yarn 1\.22\.x is/u)
  files['package.json'] = { name: 'p', version: '1.0.0', packageManager: 'pnpm@10.33.4' }
  await t.assert.rejects(load({ vfs: project(files) }), /packageManager: "pnpm@10\.33\.4" is not yarn at an exact version/u)
})

test('yarn1: links each workspace, and cwd may be in any of them', async (t) => {
  const files = {
    'package.json': { name: 'root', version: '1.0.0', private: true, workspaces: ['packages/*'] },
    'yarn.lock': LOCKFILE,
    'packages/a/package.json': { name: 'a', version: '1.0.0' },
    'packages/a/index.js': 'module.exports = 1\n',
    'packages/b/package.json': { name: 'b', version: '1.0.0', dependencies: { a: '1.0.0' } },
    'packages/b/index.js': 'require("a")\n',
  }
  const tree = await load({ vfs: project(files), cwd: '/packages/b' })
  t.assert.deepEqual([...tree.projects], ['.', 'packages/a', 'packages/b'])
  t.assert.equal(tree.stats.links, 2)
  t.assert.equal(tree.vfs.readlink('/node_modules/a'), '../packages/a')
  t.assert.equal(tree.host.resolve('/packages/b/index.js', 'a'), '/packages/a/index.js')
  // Below a package.json that is only a `type` marker, still the root's; a package of its own, not.
  t.assert.deepEqual([...(await load({ vfs: project({ ...files, 'src/package.json': { type: 'module' } }), cwd: '/src' })).projects], ['.', 'packages/a', 'packages/b'])
  await t.assert.rejects(load({ vfs: project({ ...files, 'tools/package.json': { name: 'tools', version: '1.0.0' } }), cwd: '/tools' }), (err) => err.message === "/yarn.lock does not install /tools: it is none of the lockfile's projects")
  // A workspace is installed from the root that declares it, whatever yarn.lock is nearer; a package
  // that is no workspace, from its own.
  t.assert.equal((await load({ vfs: project({ ...files, 'packages/b/yarn.lock': LOCKFILE }), cwd: '/packages/b' })).root, '/')
  const website = await load({ vfs: project({ ...files, 'website/package.json': { name: 'website', version: '1.0.0' }, 'website/yarn.lock': LOCKFILE }), cwd: '/website' })
  t.assert.deepEqual([website.root, [...website.projects]], ['/website', ['.']])
})

test('yarn1: refuses, naming the file, what it cannot reproduce', async (t) => {
  const manifest = { 'package.json': { name: 'p', version: '1.0.0' } }
  await t.assert.rejects(load({ vfs: project(manifest) }), /^Error: no yarn\.lock found in \/ or any parent directory/u)
  await t.assert.rejects(load({ vfs: project({ ...manifest, 'pnpm-lock.yaml': "lockfileVersion: '9.0'\n" }) }), /^Error: no yarn\.lock found/u, 'packageManager says which lockfile is read')
  await t.assert.rejects(load({ vfs: project({ ...manifest, 'yarn.lock': `${LOCKFILE}foo@^1:\n  version "1.0.0"\n   bad\n` }) }), (err) => err.message.startsWith('/yarn.lock: expected 2 spaces of indentation') && err.cause?.name === 'LockfileError')
  await t.assert.rejects(load({ vfs: project({ 'package.json': { name: 'p', version: '1.0.0', dependencies: { ms: '2.1.3' } }, 'yarn.lock': LOCKFILE }) }), /^Error: \/yarn\.lock: manifests\["\."\]\.dependencies\.ms: "ms@2\.1\.3" is not a pattern of the lockfile/u)
  await t.assert.rejects(load({ vfs: project({ ...manifest, 'yarn.lock': LOCKFILE, '.yarnrc': '--production true\n' }) }), /\.yarnrc:1: "--production" is a setting not supported here/u)
})

test('packageManager is one of those reproduced', async (t) => {
  const vfs = project({ 'package.json': { name: 'p', version: '1.0.0' }, 'yarn.lock': LOCKFILE })
  await Promise.all([undefined, 'yarn', 'npm', 'soldeer'].map((packageManager) => t.assert.rejects(loadNodeModules({ vfs, packageManager }), /^TypeError: loadNodeModules: packageManager must be one of 'pnpm', 'yarn1'$/u)))
  await t.assert.rejects(buildVfsBundle({ vfs, entries: ['a.js'] }), /^TypeError: buildVfsBundle: packageManager must be one of 'pnpm', 'yarn1', 'soldeer'$/u)
  await t.assert.rejects(buildVfsBundle({ vfs, packageManager: 'yarn1', entries: ['a.sol'] }), /^Error: buildVfsBundle: only JS bundles are built with yarn1$/u)
  await t.assert.rejects(buildVfsBundle({ vfs, packageManager: 'soldeer', entries: ['a.js'] }), /^Error: buildVfsBundle: only Solidity bundles are built with soldeer$/u)
})
